using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using SenorArroz.Domain.Entities;
namespace SenorArroz.Infrastructure.Data.Configurations;
public class BranchBusinessHourConfiguration:IEntityTypeConfiguration<BranchBusinessHour>{public void Configure(EntityTypeBuilder<BranchBusinessHour>b){b.ToTable("branch_business_hour");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.BranchId).HasColumnName("branch_id");b.Property(x=>x.DayOfWeek).HasColumnName("day_of_week").HasMaxLength(12).HasConversion(v=>v.ToString().ToLowerInvariant(),v=>Enum.Parse<DayOfWeek>(v,true));b.Property(x=>x.OpenTime).HasColumnName("open_time");b.Property(x=>x.CloseTime).HasColumnName("close_time");b.Property(x=>x.IsClosed).HasColumnName("is_closed");b.Property(x=>x.DisplayOrder).HasColumnName("display_order");b.Property(x=>x.CreatedAt).HasColumnName("created_at").HasDefaultValueSql("NOW()");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at").HasDefaultValueSql("NOW()");b.HasOne(x=>x.Branch).WithMany(x=>x.BusinessHours).HasForeignKey(x=>x.BranchId).OnDelete(DeleteBehavior.Cascade);b.HasIndex(x=>new{x.BranchId,x.DayOfWeek}).IsUnique();}}
